static void dwc2_wait_for_mode ( struct dwc2_hsotg * hsotg , bool host_mode ) { struct timeval start ; struct timeval end ; dev_vdbg ( hsotg -> dev , "Waiting for %s mode\n" , host_mode ?"host" : "device" ) ; getmicrotime ( & start ) ; while ( 1 ) { unsigned int ms ; if ( dwc2_is_host_mode ( hsotg ) == host_mode ) { dev_vdbg ( hsotg -> dev , "%s mode set\n" , host_mode ?"Host" : "Device" ) ; break ; } getmicrotime ( & end ) ; ms = ( end . tv_usec - start . tv_usec ) / 1000 ; if ( ms >= timeout ) { dev_warn ( hsotg -> dev , "%s: Couldn't set %s mode\n" , __func__ , host_mode ?"host" : "device" ) ; break ; } usleep_range ( 1000 , 2000 ) ; } } 